export interface Lesson {
  day: number;
  phase: number;
  phaseName: string;
  title: string;
  scriptureRef: string;
  scriptureText: string;
  lessonText: string;
  memoryHack: string;
  challenge: string;
  prayerStarter: string;
}

export const PHASES: Record<number, { name: string; days: [number, number] }> = {
  1: { name: "Who Is God?", days: [1, 15] },
  2: { name: "The Bible", days: [16, 30] },
  3: { name: "Living It Out", days: [31, 45] },
  4: { name: "Growing Forward", days: [46, 60] },
};

export function getPhaseForDay(day: number): { phase: number; phaseName: string } {
  for (const [phase, info] of Object.entries(PHASES)) {
    const [start, end] = info.days;
    if (day >= start && day <= end) {
      return { phase: Number(phase), phaseName: info.name };
    }
  }
  return { phase: 1, phaseName: "Who Is God?" };
}

